import{_ as a,o as s,c as o,a2 as r}from"./chunks/framework.DqYch1Cg.js";const u=JSON.parse('{"title":"目录结构说明","description":"","frontmatter":{},"headers":[],"relativePath":"参与贡献/目录结构说明.md","filePath":"参与贡献/目录结构说明.md","lastUpdated":1794211306000}'),t={name:"参与贡献/目录结构说明.md"};function d(c,e,i,n,l,p){return s(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="目录结构说明" tabindex="-1">目录结构说明 <a class="header-anchor" href="#目录结构说明" aria-label="Permalink to &quot;目录结构说明&quot;">​</a></h1><p>本站按两个维度组织内容：<strong>按技术领域寻找知识，按学习方式整理文章。</strong> 新增内容前，请先查找已有主题，避免重复；涉及结构性调整时，先通过 Issue 说明目的。</p><h2 id="技术领域" tabindex="-1">技术领域 <a class="header-anchor" href="#技术领域" aria-label="Permalink to &quot;技术领域&quot;">​</a></h2><p>首页与侧边栏分为五类：</p><ul><li><strong>前端开发</strong>：HTML/CSS、JavaScript、TypeScript、Vue、React、工程化等。</li><li><strong>后端开发</strong>：Node.js、NestJS、数据库与 PostgreSQL 等。</li><li><strong>AI 应用开发</strong>：大模型、Prompt、RAG、Agent 等。</li><li><strong>通用基础</strong>：算法、HTTP、浏览器、Web 安全、设计模式等。</li><li><strong>性能优化</strong>：前端、后端、数据库与 AI 应用的测量、定位和改进。</li></ul><p>分类入口由 <code>src/.vitepress/data/learning.ts</code> 维护，侧边栏领域归类由 <code>src/.vitepress/config/sidebar/groupSidebar.js</code> 维护。已有技术目录编号继续保留，编号不决定导航顺序。</p><h2 id="三种学习方式" tabindex="-1">三种学习方式 <a class="header-anchor" href="#三种学习方式" aria-label="Permalink to &quot;三种学习方式&quot;">​</a></h2><h3 id="概念与原理" tabindex="-1">概念与原理 <a class="header-anchor" href="#概念与原理" aria-label="Permalink to &quot;概念与原理&quot;">​</a></h3><p>文章位于 <code>src/概念与原理/</code>，使用 <code>s_</code> 前缀。说明是什么、解决什么问题、机制是什么，以及适用边界。可以链接对应的实践和自测。</p><h3 id="编码与实践" tabindex="-1">编码与实践 <a class="header-anchor" href="#编码与实践" aria-label="Permalink to &quot;编码与实践&quot;">​</a></h3><p>文章位于 <code>src/编码与实践/</code>，使用 <code>c_</code> 前缀。说明问题、实现思路、运行方式与观察结果。外部 demo 可以放在独立仓库，文章应链接具体文件或提交。</p><p>复杂示例可使用 <code>::: details</code> 或 <code>::: code-group</code> 渐进展示。练习不只有一种答案，比较方案时请说明约束和取舍。</p><h3 id="学习自测" tabindex="-1">学习自测 <a class="header-anchor" href="#学习自测" aria-label="Permalink to &quot;学习自测&quot;">​</a></h3><p>文章位于 <code>src/学习自测/</code>，使用 <code>q_</code> 前缀。通过问题、参考回答与追问检查理解，既能用于日常回顾，也能用于面试复习。</p><p>先检查是否有重复问题；回答尽量简洁，涉及版本差异或容易误解的结论时补充边界。</p><h2 id="文件命名" tabindex="-1">文件命名 <a class="header-anchor" href="#文件命名" aria-label="Permalink to &quot;文件命名&quot;">​</a></h2><p>技术目录映射定义在 <code>src/.vitepress/config/sidebar/usePath.js</code> 的 <code>typeMap</code> 中，例如 <code>18nestjs</code>、<code>19database</code>。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/概念与原理/02js/s_js_1-base.md</span></span>
<span class="line"><span>src/学习自测/18nestjs/q_nestjs_5-basics.md</span></span>
<span class="line"><span>src/编码与实践/02js/c_js_2-deepcopy/c_js_2-deepcopy.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>index</code> 编号用于区分文章，不决定展示顺序。创建文章后，在对应 sidebar 文件中通过 <code>useConceptItem</code>、<code>useSelfTestItem</code> 或 <code>usePracticeItem</code> 注册入口，并按需更新主题的 <code>intro.md</code>。</p><h2 id="路线、资源与历史资料" tabindex="-1">路线、资源与历史资料 <a class="header-anchor" href="#路线、资源与历史资料" aria-label="Permalink to &quot;路线、资源与历史资料&quot;">​</a></h2><ul><li><a href="/FE-prepare-interview/学习路线/index">学习路线</a>连接知识笔记、练习项目、博客和复盘，可使用<a href="/FE-prepare-interview/学习路线/实践记录模板">实践记录模板</a>记录进展。</li><li><a href="/FE-prepare-interview/性能优化/index">性能优化</a>是跨领域专题入口，缺少的实践逐步补齐。</li><li><a href="/FE-prepare-interview/学习资源/index">学习资源</a>收录外部项目、博客及早期资料入口。</li><li><code>网友面经</code>、<code>相关准备</code>保留历史语境，通过资源页访问。</li></ul><p>旧的三个核心栏目已经迁移；新增链接请使用新目录。旧 URL 的兼容跳转由构建脚本生成，无需复制旧文章。</p><h2 id="提交前验证" tabindex="-1">提交前验证 <a class="header-anchor" href="#提交前验证" aria-label="Permalink to &quot;提交前验证&quot;">​</a></h2><p>必须使用 pnpm。运行 <code>pnpm check</code> 和 <code>pnpm build</code>，确认无类型错误和死链；修改导航或页面布局时，验证桌面与移动端。引用他人内容需注明来源，AI 整理的技术内容需人工审核。</p>`,24)])])}const b=a(t,[["render",d]]);export{u as __pageData,b as default};
